command:
pwsh -NoProfile -Command & {
  $targets = @(
    'E:\iacode-audit',
    'E:\iacode-cp0009-full-verification',
    'E:\iacode-cp0009-full-verification-2',
    'E:\iacode-cp0009-full-verification-3',
    'E:\iacode-cp0009-full-verification-4',
    'E:\iacode-cp0009-full-verification-5',
    'E:\iacode-cp0009-full-verification-6',
    'E:\iacode-m0-final-audit-c53f4c5'
  )
  $workspace = [IO.Path]::GetFullPath('E:\iacode').TrimEnd('\')
  $inventory = Get-Content -LiteralPath 'E:\iacode\docs\checkpoints\GATE-4-CP-0009\FILES.json' -Raw
  $worktreeLines = @(git -C $workspace worktree list --porcelain)
  $worktrees = @($worktreeLines | Where-Object { $_ -like 'worktree *' } | ForEach-Object { [IO.Path]::GetFullPath($_.Substring(9)).TrimEnd('\') })
  foreach ($target in $targets) {
    if (-not (Test-Path -LiteralPath $target -PathType Container)) { throw "missing authorized target: $target" }
    $resolved = (Resolve-Path -LiteralPath $target).Path.TrimEnd('\')
    $expected = [IO.Path]::GetFullPath($target).TrimEnd('\')
    if (-not [StringComparer]::OrdinalIgnoreCase.Equals($resolved, $expected)) { throw "resolved path changed: $target -> $resolved" }
    if (-not [StringComparer]::OrdinalIgnoreCase.Equals([IO.Path]::GetDirectoryName($resolved), 'E:\')) { throw "target left authorized parent: $resolved" }
    if ([StringComparer]::OrdinalIgnoreCase.Equals($resolved, $workspace) -or $resolved.StartsWith($workspace + '\', [StringComparison]::OrdinalIgnoreCase)) { throw "target overlaps workspace: $resolved" }
    $item = Get-Item -LiteralPath $resolved -Force
    if (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { throw "reparse target refused: $resolved" }
    if ($worktrees | Where-Object { [StringComparer]::OrdinalIgnoreCase.Equals($_, $resolved) }) { throw "registered worktree refused: $resolved" }
    if ($inventory.Contains($item.Name)) { throw "checkpoint inventory names target: $resolved" }
    if ($item.Name -eq 'iacode-audit') {
      $children = @(Get-ChildItem -LiteralPath $resolved -Directory -Force)
      $rootFiles = @(Get-ChildItem -LiteralPath $resolved -File -Force)
      if ($children.Count -ne 2 -or $rootFiles.Count -ne 0) { throw "unexpected audit scratch shape: $resolved" }
      foreach ($child in $children) {
        if (-not (Test-Path -LiteralPath (Join-Path $child.FullName '.git'))) { throw "audit child is not a clone: $($child.FullName)" }
        $top = (& git -C $child.FullName rev-parse --show-toplevel 2>$null) -join ''
        $top = [IO.Path]::GetFullPath($top).TrimEnd('\')
        if (-not [StringComparer]::OrdinalIgnoreCase.Equals($top, $child.FullName.TrimEnd('\'))) { throw "audit child git root mismatch: $($child.FullName)" }
        $origin = ((& git -C $child.FullName remote get-url origin 2>$null) -join '')
        if ($origin -ne 'https://github.com/pinguim16/iacode.git') { throw "unexpected audit clone origin: $origin" }
      }
    } else {
      if (-not (Test-Path -LiteralPath (Join-Path $resolved '.git'))) { throw "scratch clone marker missing: $resolved" }
      $top = ((& git -C $resolved rev-parse --show-toplevel 2>$null) -join '')
      $top = [IO.Path]::GetFullPath($top).TrimEnd('\')
      if (-not [StringComparer]::OrdinalIgnoreCase.Equals($top, $resolved)) { throw "scratch clone git root mismatch: $resolved" }
      $origin = ((& git -C $resolved remote get-url origin 2>$null) -join '')
      if ($origin -notin @('https://github.com/pinguim16/iacode.git','E:\iacode')) { throw "unexpected scratch clone origin: $origin" }
    }
  }
  foreach ($target in $targets) {
    Remove-Item -LiteralPath $target -Recurse -Force
    if (Test-Path -LiteralPath $target) { throw "removal incomplete: $target" }
    Write-Output "REMOVED_VERIFIED_SCRATCH=$target"
  }
}

