command:
pwsh -NoProfile -Command & {
  $self = $PID
  $active = @(Get-CimInstance Win32_Process | Where-Object {
    $_.ProcessId -ne $self -and $_.Name -match '^python|^git|^docker' -and $_.CommandLine -match 'green_keeper|unittest discover -s tests|m0_mirror_audit|gate4_red_team|check_completeness|run_checkpoint_validation'
  })
  if ($active.Count -ne 0) {
    $active | Select-Object ProcessId,ParentProcessId,Name,CommandLine | ConvertTo-Json -Depth 3
    exit 1
  }
  Write-Output 'NO_ACTIVE_ASSURANCE_PROCESS controlled-cycle-19-interruption-complete'
}

