command:
pwsh -NoProfile -Command & {
  $tempRoot = [IO.Path]::GetTempPath().TrimEnd('\')
  $temp = @(Get-ChildItem -LiteralPath $tempRoot -Directory -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -like 'iacode-history-*' -or $_.Name -like 'iacode-clean-clone-*' })
  $drive = @(Get-ChildItem -LiteralPath 'E:\' -Directory -Force | Where-Object { $_.Name -match '^iacode-.*(?:audit|full-verification)' })
  $repo = @(Get-ChildItem -LiteralPath 'E:\iacode' -Directory -Force | Where-Object { $_.Name -match '^iacode-.*(?:audit|full-verification)' })
  $all = @($temp) + @($drive) + @($repo)
  if ($all.Count -ne 0) {
    $all | Select-Object -ExpandProperty FullName
    exit 1
  }
  Write-Output 'SCRATCH_CLEAN verified-absent temp=0 drive=0 repository=0'
}

